+  EXPECT_DOUBLE_EQ(catalog->edges[1].polyline[0].second, 0.0);
+  EXPECT_DOUBLE_EQ(catalog->edges[1].polyline[1].first, 5.0);
+  EXPECT_DOUBLE_EQ(catalog->edges[1].polyline[1].second, 5.0);
+  // 后续边不受前一条边 polyline 块影响
