+  ASSERT_EQ(catalog->edges[2].polyline.size(), 2u);
+  EXPECT_DOUBLE_EQ(catalog->edges[2].polyline[1].first, 10.0);
+  EXPECT_DOUBLE_EQ(catalog->edges[2].polyline[1].second, 0.0);
+}
