1	#include "amr_dispatcher_core/catalog/station_catalog.hpp"
2	
3	#include <algorithm>
4	#include <cmath>
5	#include <fstream>
6	#include <limits>
7	#include <sstream>
8	#include <string>
9	#include <unordered_set>
10	#include <vector>
11	
12	namespace amr_dispatcher_core::catalog {
13	namespace {
14	
15	std::string Trim(const std::string& value) {
16	  auto first = value.find_first_not_of(" \t\r\n");
17	  if (first == std::string::npos) {
18	    return "";
19	  }
20	  auto last = value.find_last_not_of(" \t\r\n");
21	  std::string s = value.substr(first, last - first + 1);
22	  // 去除 YAML 引号包裹：例如 "station_pickup_A" 或 'station_pickup_A'
23	  if (s.size() >= 2 && ((s.front() == '"' && s.back() == '"') || (s.front() == '\'' && s.back() == '\''))) {
24	    s = s.substr(1, s.size() - 2);
25	  }
26	  return s;
27	}
28	
29	std::optional<std::string> ValueAfterColon(const std::string& line, const std::string& key) {
30	  const std::string prefix = key + ":";
31	  if (line.rfind(prefix, 0) != 0) {
32	    return std::nullopt;
33	  }
34	  return Trim(line.substr(prefix.size()));
35	}
36	
37	std::optional<double> ParseDouble(const std::string& value) {
38	  std::istringstream parser(value);
39	  double result = 0.0;
40	  parser >> result;
41	  if (parser.fail() || !std::isfinite(result)) {
42	    return std::nullopt;
43	  }
44	  return result;
45	}
46	
47	bool ParseBool(const std::string& value) {
48	  return value == "true" || value == "True" || value == "1";
49	}
50	
51	// 解析 "- [1.5, 2.0]" 形式的 flow 折线点（取前两个分量）
52	std::optional<std::pair<double, double>> ParseFlowPoint(const std::string& content) {
53	  if (content.size() < 2 || content.front() != '[' || content.back() != ']') {
54	    return std::nullopt;
55	  }
56	  const std::string inner = content.substr(1, content.size() - 2);
57	  const auto comma = inner.find(',');
58	  if (comma == std::string::npos) {
59	    return std::nullopt;
60	  }
61	  const auto x = ParseDouble(Trim(inner.substr(0, comma)));
62	  const auto y = ParseDouble(Trim(inner.substr(comma + 1)));
63	  if (!x || !y) {
64	    return std::nullopt;
65	  }
66	  return std::pair<double, double>{*x, *y};
67	}
68	
69	// edge 自身字段键（用于识别折线块何时结束）
70	bool IsEdgeFieldKey(const std::string& line) {
71	  return ValueAfterColon(line, "from").has_value() ||
72	         ValueAfterColon(line, "to").has_value() ||
73	         ValueAfterColon(line, "distance_m").has_value() ||
74	         ValueAfterColon(line, "distance").has_value() ||
75	         ValueAfterColon(line, "bidirectional").has_value() ||
76	         ValueAfterColon(line, "enabled").has_value();
77	}
78	
79	}  // namespace
80	
81	std::optional<StationCatalog> LoadStationCatalog(const std::filesystem::path& path) {
82	  std::ifstream input(path);
83	  if (!input) {
84	    return std::nullopt;
85	  }
86	
87	  StationCatalog catalog;
88	  Station current_station;
89	  RoadNode current_road_node;
90	  CatalogStationEdge current_edge;
91	  std::string default_frame_id = "map";
92	  std::string section;
93	  bool in_station = false;
94	  bool in_road_node = false;
95	  bool in_edge = false;
96	  bool in_polyline = false;
97	  bool has_id = false;
98	  bool has_x = false;
99	  bool has_y = false;
100	  bool has_node_id = false;
101	  bool has_node_x = false;
102	  bool has_node_y = false;
103	  bool has_from = false;
104	  bool has_to = false;
105	  bool has_distance = false;
106	  // map 风格折线点（- x: ... / y: ...）的暂存分量
107	  std::pair<double, double> pending_point{0.0, 0.0};
108	  bool point_has_x = false;
109	  bool point_has_y = false;
110	
111	  auto flush_polyline_point = [&]() {
112	    if (point_has_x && point_has_y) {
113	      current_edge.polyline.push_back(pending_point);
114	    }
115	    pending_point = std::pair<double, double>{0.0, 0.0};
116	    point_has_x = false;
117	    point_has_y = false;
118	  };
119	
120	  auto flush_station = [&]() {
121	    if (in_station && has_id && has_x && has_y) {
122	      if (current_station.frame_id.empty()) {
123	        current_station.frame_id = default_frame_id;
124	      }
125	      catalog.stations.push_back(current_station);
126	    }
127	    current_station = Station{};
128	    current_station.frame_id = default_frame_id;
129	    in_station = false;
130	    has_id = false;
131	    has_x = false;
132	    has_y = false;
133	  };
134	
135	  auto flush_road_node = [&]() {
136	    if (in_road_node && has_node_id && has_node_x && has_node_y) {
137	      if (current_road_node.frame_id.empty()) {
138	        current_road_node.frame_id = default_frame_id;
139	      }
140	      catalog.road_nodes.push_back(current_road_node);
141	    }
142	    current_road_node = RoadNode{};
143	    current_road_node.frame_id = default_frame_id;
144	    in_road_node = false;
145	    has_node_id = false;
146	    has_node_x = false;
147	    has_node_y = false;
148	  };
149	
150	  auto flush_edge = [&]() {
151	    flush_polyline_point();
152	    if (in_edge && has_from && has_to && has_distance) {
153	      catalog.edges.push_back(current_edge);
154	    }
155	    current_edge = CatalogStationEdge{};
156	    in_edge = false;
157	    in_polyline = false;
158	    has_from = false;
159	    has_to = false;
160	    has_distance = false;
161	  };
162	
163	  std::string line;
164	  while (std::getline(input, line)) {
165	    line = Trim(line);
166	    if (line.empty() || line.front() == '#') {
167	      continue;
168	    }
169	
170	    if (line == "stations:" || line == "edges:" || line == "routes:" || line == "road_nodes:" ||
171	        line == "version:") {
172	      flush_station();
173	      flush_road_node();
174	      flush_edge();
175	      section = line.substr(0, line.size() - 1);
176	      continue;
177	    }
178	
179	    if (!in_station && !in_edge && !in_road_node) {
180	      if (auto value = ValueAfterColon(line, "frame_id")) {
181	        default_frame_id = value->empty() ? "map" : *value;
182	        current_station.frame_id = default_frame_id;
183	        current_road_node.frame_id = default_frame_id;
184	        continue;
185	      }
186	      if (auto value = ValueAfterColon(line, "map_hash")) {
187	        catalog.map_hash = *value;
188	        continue;
189	      }
190	      if (auto value = ValueAfterColon(line, "graph_version")) {
191	        catalog.graph_version = *value;
192	        continue;
193	      }
194	    }
195	
196	    if (line.rfind("- ", 0) == 0) {
197	      const std::string content = Trim(line.substr(2));
198	      if (in_polyline && !content.empty() && content.front() == '[') {
199	        // flow 风格折线点：- [x, y]
200	        if (auto point = ParseFlowPoint(content)) {
201	          flush_polyline_point();
202	          current_edge.polyline.push_back(*point);
203	        }
204	        continue;
205	      }
206	      if (in_polyline && (ValueAfterColon(content, "x") || ValueAfterColon(content, "y"))) {
207	        // map 风格折线点起始：- x: ... / - y: ...
208	        flush_polyline_point();
209	        if (auto value = ValueAfterColon(content, "x")) {
210	          if (auto parsed = ParseDouble(*value)) {
211	            pending_point.first = *parsed;
212	            point_has_x = true;
213	          }
214	        } else if (auto value = ValueAfterColon(content, "y")) {
215	          if (auto parsed = ParseDouble(*value)) {
216	            pending_point.second = *parsed;
217	            point_has_y = true;
218	          }
219	        }
220	        continue;
221	      }
222	      if (in_polyline) {
223	        // 折线块内的其他 "- " 条目：结束折线并开始下一条边
224	        flush_edge();
225	        in_edge = true;
226	      } else if (section == "edges" || section == "routes") {
227	        flush_edge();
228	        in_edge = true;
229	      } else if (section == "road_nodes") {
230	        flush_road_node();
231	        in_road_node = true;
232	        current_road_node.frame_id = default_frame_id;
233	      } else {
234	        flush_station();
235	        in_station = true;
236	        current_station.frame_id = default_frame_id;
237	      }
238	      line = content;
239	    }
240	
241	    if (in_edge) {
242	      if (ValueAfterColon(line, "polyline")) {
243	        flush_polyline_point();
244	        in_polyline = true;
245	        continue;
246	      }
247	      if (in_polyline) {
248	        if (IsEdgeFieldKey(line)) {
249	          flush_polyline_point();
250	          in_polyline = false;  // 折线块结束，继续按 edge 字段解析本行
251	        } else if (auto value = ValueAfterColon(line, "x")) {
252	          flush_polyline_point();
253	          if (auto parsed = ParseDouble(*value)) {
254	            pending_point.first = *parsed;
255	            point_has_x = true;
256	          }
257	          continue;
258	        } else if (auto value = ValueAfterColon(line, "y")) {
259	          if (auto parsed = ParseDouble(*value)) {
260	            pending_point.second = *parsed;
261	            point_has_y = true;
262	          }
263	          continue;
264	        } else {
265	          continue;  // 折线块内的其余行忽略
266	        }
267	      }
268	      if (auto value = ValueAfterColon(line, "from")) {
269	        current_edge.from = *value;
270	        has_from = !current_edge.from.empty();
271	        continue;
272	      }
273	      if (auto value = ValueAfterColon(line, "to")) {
274	        current_edge.to = *value;
275	        has_to = !current_edge.to.empty();
276	        continue;
277	      }
278	      if (auto value = ValueAfterColon(line, "distance_m")) {
279	        if (auto parsed = ParseDouble(*value)) {
280	          current_edge.distance_m = *parsed;
281	          has_distance = true;
282	        }
283	        continue;
284	      }
285	      if (auto value = ValueAfterColon(line, "distance")) {
286	        if (auto parsed = ParseDouble(*value)) {
287	          current_edge.distance_m = *parsed;
288	          has_distance = true;
289	        }
290	        continue;
291	      }
292	      if (auto value = ValueAfterColon(line, "bidirectional")) {
293	        current_edge.bidirectional = ParseBool(*value);
294	        continue;
295	      }
296	      if (auto value = ValueAfterColon(line, "enabled")) {
297	        current_edge.enabled = ParseBool(*value);
298	        continue;
299	      }
300	      continue;
301	    }
302	
303	    if (in_road_node) {
304	      if (auto value = ValueAfterColon(line, "id")) {
305	        current_road_node.id = *value;
306	        has_node_id = !current_road_node.id.empty();
307	        continue;
308	      }
309	      if (auto value = ValueAfterColon(line, "frame_id")) {
310	        current_road_node.frame_id = value->empty() ? default_frame_id : *value;
311	        continue;
312	      }
313	      if (auto value = ValueAfterColon(line, "x")) {
314	        if (auto parsed = ParseDouble(*value)) {
315	          current_road_node.x = *parsed;
316	          has_node_x = true;
317	        }
318	        continue;
319	      }
320	      if (auto value = ValueAfterColon(line, "y")) {
321	        if (auto parsed = ParseDouble(*value)) {
322	          current_road_node.y = *parsed;
323	          has_node_y = true;
324	        }
325	        continue;
326	      }
327	      if (auto value = ValueAfterColon(line, "yaw")) {
328	        if (auto parsed = ParseDouble(*value)) {
329	          current_road_node.yaw = *parsed;
330	        }
331	        continue;
332	      }
333	      continue;  // road_nodes 条目内的其他字段（如 type）忽略
334	    }
335	
336	    if (auto value = ValueAfterColon(line, "id")) {
337	      current_station.id = *value;
338	      has_id = !current_station.id.empty();
339	      continue;
340	    }
341	    if (auto value = ValueAfterColon(line, "frame_id")) {
342	      current_station.frame_id = value->empty() ? default_frame_id : *value;
343	      continue;
344	    }
345	    if (auto value = ValueAfterColon(line, "x")) {
346	      if (auto parsed = ParseDouble(*value)) {
347	        current_station.x = *parsed;
348	        has_x = true;
349	      }
350	      continue;
351	    }
352	    if (auto value = ValueAfterColon(line, "y")) {
353	      if (auto parsed = ParseDouble(*value)) {
354	        current_station.y = *parsed;
355	        has_y = true;
356	      }
357	      continue;
358	    }
359	    if (auto value = ValueAfterColon(line, "yaw")) {
360	      if (auto parsed = ParseDouble(*value)) {
361	        current_station.yaw = *parsed;
362	      }
363	      continue;
364	    }
365	  }
366	  flush_station();
367	  flush_road_node();
368	  flush_edge();
369	
370	  std::string message;
371	  if (!ValidateStationCatalog(catalog, &message)) {
372	    return std::nullopt;
373	  }
374	  return catalog;
375	}
