386	std::optional<double> EstimateRouteDistance(
387	    const StationCatalog& catalog, const std::string& from, const std::string& to) {
388	  const auto path = FindRoutePath(catalog, from, to);
389	  if (!path.has_value()) {
390	    return std::nullopt;
391	  }
392	  double distance_m = 0.0;
393	  for (std::size_t index = 1; index < path->size(); ++index) {
394	    for (const auto& edge : catalog.edges) {
395	      const bool forward = edge.from == (*path)[index - 1] && edge.to == (*path)[index];
396	      const bool reverse =
397	          edge.bidirectional && edge.to == (*path)[index - 1] && edge.from == (*path)[index];
398	      if (edge.enabled && (forward || reverse)) {
399	        distance_m += edge.distance_m;
400	        break;
401	      }
402	    }
403	  }
404	  return distance_m;
405	}
