407	std::optional<std::vector<std::string>> FindRoutePath(
408	    const StationCatalog& catalog, const std::string& from, const std::string& to) {
409	  if (from == to) {
410	    return std::vector<std::string>{from};
411	  }
412	
413	  std::vector<std::string> ids;
414	  ids.reserve(catalog.stations.size() + catalog.road_nodes.size());
415	  for (const auto& station : catalog.stations) {
416	    ids.push_back(station.id);
417	  }
418	  // 通行节点与站点共用同一图节点集合，支持途经路口的混合图寻路
419	  for (const auto& road_node : catalog.road_nodes) {
420	    ids.push_back(road_node.id);
421	  }
422	  const auto index_of = [&](const std::string& id) -> std::optional<std::size_t> {
423	    const auto it = std::find(ids.begin(), ids.end(), id);
424	    if (it == ids.end()) {
425	      return std::nullopt;
426	    }
427	    return static_cast<std::size_t>(std::distance(ids.begin(), it));
428	  };
429	
430	  const auto start = index_of(from);
431	  const auto goal = index_of(to);
432	  if (!start.has_value() || !goal.has_value()) {
433	    return std::nullopt;
434	  }
435	
436	  const double infinity = std::numeric_limits<double>::infinity();
437	  std::vector<double> distance(ids.size(), infinity);
438	  std::vector<std::optional<std::size_t>> previous(ids.size(), std::nullopt);
439	  std::vector<bool> visited(ids.size(), false);
440	  distance[*start] = 0.0;
441	
442	  for (std::size_t iteration = 0; iteration < ids.size(); ++iteration) {
443	    std::optional<std::size_t> current;
444	    for (std::size_t i = 0; i < ids.size(); ++i) {
445	      if (!visited[i] && (!current.has_value() || distance[i] < distance[*current])) {
446	        current = i;
447	      }
448	    }
449	    if (!current.has_value() || !std::isfinite(distance[*current])) {
450	      break;
451	    }
452	    if (*current == *goal) {
453	      break;
454	    }
455	    visited[*current] = true;
456	
457	    for (const auto& edge : catalog.edges) {
458	      if (!edge.enabled) {
459	        continue;
460	      }
461	      const auto edge_from = index_of(edge.from);
462	      const auto edge_to = index_of(edge.to);
463	      if (!edge_from.has_value() || !edge_to.has_value()) {
464	        continue;
465	      }
466	      auto relax = [&](const std::size_t source, const std::size_t target) {
467	        if (source == *current && distance[source] + edge.distance_m < distance[target]) {
468	          distance[target] = distance[source] + edge.distance_m;
469	          previous[target] = source;
470	        }
471	      };
472	      relax(*edge_from, *edge_to);
473	      if (edge.bidirectional) {
474	        relax(*edge_to, *edge_from);
475	      }
476	    }
477	  }
478	  if (!std::isfinite(distance[*goal])) {
479	    return std::nullopt;
480	  }
481	  std::vector<std::string> path;
482	  for (auto current = *goal;;) {
483	    path.push_back(ids[current]);
484	    if (current == *start) {
485	      break;
486	    }
487	    if (!previous[current].has_value()) {
488	      return std::nullopt;
489	    }
490	    current = *previous[current];
491	  }
492	  std::reverse(path.begin(), path.end());
493	  return path;
494	}
