496	bool ValidateStationCatalog(const StationCatalog& catalog, std::string* message) {
497	  if (catalog.stations.empty()) {
498	    if (message != nullptr) {
499	      *message = "station catalog is empty";
500	    }
501	    return false;
502	  }
503	
504	  std::unordered_set<std::string> ids;
505	  for (const auto& station : catalog.stations) {
506	    if (station.id.empty()) {
507	      if (message != nullptr) {
508	        *message = "station id is empty";
509	      }
510	      return false;
511	    }
512	    if (station.frame_id.empty()) {
513	      if (message != nullptr) {
514	        *message = "station frame_id is empty: " + station.id;
515	      }
516	      return false;
517	    }
518	    if (!std::isfinite(station.x) || !std::isfinite(station.y) || !std::isfinite(station.yaw)) {
519	      if (message != nullptr) {
520	        *message = "station pose is not finite: " + station.id;
521	      }
522	      return false;
523	    }
524	    if (!ids.insert(station.id).second) {
525	      if (message != nullptr) {
526	        *message = "duplicate station id: " + station.id;
527	      }
528	      return false;
529	    }
530	  }
531	
532	  // road_nodes 与 stations 共用同一 id 空间：集合内与跨集合均不允许重复
533	  for (const auto& road_node : catalog.road_nodes) {
534	    if (road_node.id.empty()) {
535	      if (message != nullptr) {
536	        *message = "road node id is empty";
537	      }
538	      return false;
539	    }
540	    if (road_node.frame_id.empty()) {
541	      if (message != nullptr) {
542	        *message = "road node frame_id is empty: " + road_node.id;
543	      }
544	      return false;
545	    }
546	    if (!std::isfinite(road_node.x) || !std::isfinite(road_node.y) ||
547	        !std::isfinite(road_node.yaw)) {
548	      if (message != nullptr) {
549	        *message = "road node pose is not finite: " + road_node.id;
550	      }
551	      return false;
552	    }
553	    if (!ids.insert(road_node.id).second) {
554	      if (message != nullptr) {
555	        *message = "duplicate road node id: " + road_node.id;
556	      }
557	      return false;
558	    }
559	  }
560	
561	  for (const auto& edge : catalog.edges) {
562	    if (edge.from.empty() || edge.to.empty()) {
563	      if (message != nullptr) {
564	        *message = "station edge endpoint is empty";
565	      }
566	      return false;
567	    }
568	    if (ids.find(edge.from) == ids.end()) {
569	      if (message != nullptr) {
570	        *message = "station edge has unknown from endpoint: " + edge.from;
571	      }
572	      return false;
573	    }
574	    if (ids.find(edge.to) == ids.end()) {
575	      if (message != nullptr) {
576	        *message = "station edge has unknown to endpoint: " + edge.to;
577	      }
578	      return false;
579	    }
580	    if (!std::isfinite(edge.distance_m) || edge.distance_m < 0.0) {
581	      if (message != nullptr) {
582	        *message = "station edge distance is invalid: " + edge.from + " -> " + edge.to;
583	      }
584	      return false;
585	    }
586	    for (const auto& point : edge.polyline) {
587	      if (!std::isfinite(point.first) || !std::isfinite(point.second)) {
588	        if (message != nullptr) {
589	          *message = "station edge polyline point is not finite: " + edge.from + " -> " + edge.to;
590	        }
591	        return false;
592	      }
593	    }
594	  }
595	
596	  if (message != nullptr) {
597	    *message = "ok";
598	  }
599	  return true;
600	}
