639	StationCatalogReloader::StationCatalogReloader(std::filesystem::path path)
640	    : path_(std::move(path)),
641	      watcher_(path_.string(), [this](const YAML::Node&) { TryLoad(true); }) {
642	  TryLoad(false);   // 初始加载等价节点 on_configure 的一次性读取
643	  watcher_.Tick();  // 建立 mtime 基线：首拍只记基线不回调，之后的变化才重载
644	}
645	
646	bool StationCatalogReloader::Tick() {
647	  const auto before = reload_count_;
648	  watcher_.Tick();
649	  if (!watcher_.last_error().empty()) {
650	    last_error_ = watcher_.last_error();  // YAML 解析失败：回调未触发，旧目录保持
651	  }
652	  return reload_count_ > before;
653	}
654	
655	std::string StationCatalogReloader::last_error() const {
656	  return last_error_;
657	}
658	
659	void StationCatalogReloader::TryLoad(bool count_as_reload) {
660	  if (auto loaded = LoadStationCatalog(path_)) {
661	    catalog_ = std::move(*loaded);
662	    loaded_ = true;
663	    if (count_as_reload) {
664	      ++reload_count_;
665	    }
666	    last_error_.clear();
667	  } else {
668	    // 校验失败（空目录、重复 id、非法位姿等）：保留旧目录，记录错误
669	    last_error_ = "station catalog invalid or unreadable: " + path_.string();
670	  }
671	}
